function maximumTripletValue(nums) {
  let best = 0;
  let maxLeft = 0;
  let maxDiff = 0;
  for (let k = 0; k < nums.length; k++) {
    best = Math.max(best, maxDiff * nums[k]);
    maxDiff = Math.max(maxDiff, maxLeft - nums[k]);
    maxLeft = Math.max(maxLeft, nums[k]);
  }
  return best;
}

