function generate(rand, size) {
  if (size === 'large') {
    return [Array.from({ length: 100 }, () => 1 + Math.floor(rand() * 1e6))];
  }
  const n = 3 + Math.floor(rand() * 6);
  const top = rand() < 0.2 ? 1e6 : rand() < 0.5 ? 5 : 30;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
